		public static bool IsCompressedFormat(this DxgiFormat format)
		{
			if (format - 70 <= DxgiFormat.DxgiFormatR16G16B16A16Sint || format - 94 <= DxgiFormat.DxgiFormatR32G32B32Typeless || format - 300 <= DxgiFormat.DxgiFormatR32G32B32A32Float)
			{
				return true;
			}
			return false;
		}
